import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Filigran, fotoğrafınızın üzerine koyduğunuz görünür bir imzadır. Emeğinizi korur ve markanızı duyurur.</p>\n<p>İyi bir filigran, fotoğrafı bozmadan korur. Kötü bir filigran ise görseli mahveder ve izleyiciyi uzaklaştırır.</p>\n<p>Bu kılavuz, metin ve logo filigranlarını, opaklık ile yerleşimi ve filigranın yasal olarak ne yapıp ne yapamayacağını anlatıyor.</p>\n<h2 id=\"what-is-a-watermark\">Filigran nedir?</h2>\n<p>Filigran, görselin üzerine eklenen yarı saydam işaret ya da yazıdır. Fotoğrafın size ait olduğunu gösterir.</p>\n<p>Filigranlar yüzyıllardır kullanılır. Kâğıt filigranları, paranın sahte olmadığını kanıtlardı.</p>\n<p>Dijital filigran, aynı işi görselde yapar. İzinsiz kullanımı zorlaştırır ve kaynağı gösterir.</p>\n<h2 id=\"text-vs-logo-watermarks\">Metin filigranı ve logo filigranı</h2>\n<p>Metin filigranı, adınızı ya da sitenizi yazar. Hızlıdır ve her fotoğrafta kullanılabilir.</p>\n<p>Logo filigranı, marka işaretinizi kullanır. Daha profesyonel görünür ama logo dosyası gerekir.</p>\n<p>Seçim, amaca bağlıdır. Hızlı koruma için metin, marka için logo kullanın.</p>\n<h2 id=\"tiled-repeat-pattern\">Döşemeli tekrar deseni</h2>\n<p>Döşemeli desen, filigranı görselin her yerine tekrarlar. Kırpmayla kurtulmak imkânsız hâle gelir.</p>\n<p>Bu desen, müşteri önizlemelerinde kullanılır. Müşteri fotoğrafı görür ama izinsiz kullanamaz.</p>\n<p>Desen, görseli bozmamalıdır. Opaklığı düşük tutun; fotoğraf hâlâ görülmelidir.</p>\n<h2 id=\"opacity-and-visibility\">Opaklık: koruyacak kadar görünür, görecek kadar hafif</h2>\n<p>Opaklık, filigranın ne kadar belirgin olduğunu belirler. Yüzde 100 opak filigran fotoğrafı kapatır.</p>\n<p>Müşteri önizlemelerinde yüzde 40-50 opaklık kullanın. Filigran okunur ama fotoğraf görülür.</p>\n<p>Sosyal medyada yüzde 20-30 yeterlidir. Hafif filigran, markayı duyurur ama görseli bozmaz.</p>\n<h2 id=\"placement-strategy\">Filigran nereye koyulmalı?</h2>\n<p>Köşe, en yaygın yerdir ama en kolay kırpılan yerdir. Köşedeki filigran, kırpmayla gider.</p>\n<p>Merkez, en güvenli yerdir ama fotoğrafı böler. Önizlemelerde merkez kullanılır; finalde köşe kullanılır.</p>\n<p>Kenar ortası, iyi bir denge sunar. Kırpması zordur ve fotoğrafı az böler.</p>\n<h2 id=\"text-size-and-scaling\">Metin boyutu: küçük ve büyük fotoğraflar</h2>\n<p>Filigran boyutu, fotoğraf boyutuna göre ayarlanmalıdır. Küçük fotoğrafta büyük filigran, görseli kapatır.</p>\n<p>Araçta filigran boyutunu fotoğrafın yüzde 5-10'u olarak ayarlayın; bu ölçüde filigran okunur ama göze batmaz.</p>\n<p>Toplu filigranlamada boyutu orantılı tutun. Tüm fotoğraflarda aynı görünmelidir.</p>\n<h2 id=\"watermark-colour-and-contrast\">Filigran rengi ve kontrastı: okunur hâle getirmek</h2>\n<p>Araçta beyaz filigran, koyu karede net okunur ama açık karede kaybolur; rengi fotoğrafın tonuna göre seçin.</p>\n<p>Araçta filigran yazısına kontur ekleyin; beyaz yazıya siyah kontur, her türlü zeminde okunur kalır.</p>\n<p>Marka rengi kullanabilirsiniz. Renk, markayı duyurur ama okunabilirlik önce gelir.</p>\n<h2 id=\"rotation-and-angle\">Döndürme ve açı</h2>\n<p>Çapraz filigran, kırpması zor bir işarettir. 45 derecelik açı, görselin her yerine yayılır.</p>\n<p>Çapraz filigran, önizlemelerde kullanılır. Final görsellerde düz filigran daha zariftir.</p>\n<p>Açıyı abartmayın. Hafif eğik filigran zarif görünür; dik filigran dikkat dağıtır.</p>\n<h2 id=\"formats-and-transparency\">Formatlar, saydamlık ve dışa aktarma</h2>\n<p>Logo filigranı için PNG kullanın. PNG saydamlığı destekler; logo arka plansız durur.</p>\n<p>Filigranlı fotoğraflar için JPG idealdir. Küçük dosya, hızlı paylaşım demektir.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Filigranın konumu ve opaklığı doğru olmalıdır.</p>\n<h2 id=\"watermark-vs-copyright\">Filigran ve telif hakkı: filigran ne yapabilir, ne yapamaz?</h2>\n<p>Filigran, sahipliği gösterir ama yasal koruma sağlamaz. Telif hakkı, yasayla gelir; filigran yalnızca işarettir.</p>\n<p>Araçla eklenen filigran, izinsiz kullanımı caydırır; çoğu kişi, filigranlı kareyi alıp kullanmaktan vazgeçer.</p>\n<p>Filigranın yasal koruma sağlamadığını unutmayın; kanıt olarak işe yarasa da telif kaydı olmadan tek başına yeterli değildir.</p>\n<h2 id=\"privacy-and-local-processing\">Gizlilik: hiçbir şey yüklemeden filigranlamak</h2>\n<p>Filigran aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu, müşteri fotoğrafları için önemlidir. Gizli işleri güvenle filigranlayabilirsiniz.</p>\n<p>Sekmeyi kapattığınızda veriler silinir. Fotoğraflarınız yalnızca sizde kalır.</p>\n<h2 id=\"common-watermark-mistakes\">Filigranla yaygın hatalar</h2>\n<p>En yaygın hata, çok opak filigrandır. Fotoğrafı kapatan filigran, izleyiciyi uzaklaştırır.</p>\n<p>Bir başka hata, köşeye koymaktır. Köşedeki filigran, kırpmayla gider.</p>\n<p>Üçüncü hata, çok küçük filigrandır. Okunamayan filigran, koruma sağlamaz.</p>\n<h2 id=\"watermark-workflow\">Müşteri önizlemeleri için filigran akışı</h2>\n<p>Müşteriye göndermeden önce tüm fotoğrafları filigranlayın. Döşemeli desen kullanın; kırpma kurtarmaz.</p>\n<p>Araçta opaklığı yüzde 40-50 arasında tutun; müşteri fotoğrafı net görür ama filigran, kullanımı engeller.</p>\n<p>Müşteri ödeme yapınca araçta filigransız sürümü indirin; temiz dosya, ödemenin karşılığı olarak teslim edilir.</p>\n<h2 id=\"watermarking-social-media\">Sosyal medya için filigran</h2>\n<p>Sosyal medyada hafif filigran kullanın. Yüzde 20-30 opaklık, markayı duyurur ama görseli bozmaz.</p>\n<p>Araçta filigranı köşeye yerleştirmeyin; platform görseli kırparsa köşedeki filigran kaybolur.</p>\n<p>Araçta filigrana marka adınızı yazın; paylaşılan her görsel, markanızı da beraberinde taşır.</p>\n<h2 id=\"watermarking-stock-photos\">Stok fotoğraf ve önizlemelerde filigran</h2>\n<p>Stok siteleri, önizlemelere filigran koyar. Müşteri fotoğrafı görür ama satın almadan kullanamaz.</p>\n<p>Döşemeli desen kullanın. Tek filigran, kırpmayla gider; desen gitmez.</p>\n<p>Satın alma sonrası temiz sürüm verilir. Filigran, ödeme duvarıdır.</p>\n<h2 id=\"watermark-removal-myths\">Filigran kaldırma efsaneleri</h2>\n<p>Efsane: filigran her zaman kaldırılabilir. Gerçek: döşemeli desen, kaldırılması çok zor bir işarettir.</p>\n<p>Efsane: yapay zekâ filigranı siler. Gerçek: yapay zekâ bazen siler ama fotoğrafı da bozar.</p>\n<p>Efsane: filigran yasal koruma sağlar. Gerçek: filigran yalnızca işarettir; yasal koruma kayıttan gelir.</p>\n<h2 id=\"watermarking-and-branding\">Marka olarak filigran</h2>\n<p>Filigran, markanızın imzasıdır. Tutarlı filigran, işinizi tanınır kılar.</p>\n<p>Her fotoğrafta aynı filigranı kullanın. Tutarlılık, marka bilinirliği yaratır.</p>\n<p>Filigranı sade tutun. Karmaşık filigran, okunamaz ve markayı zayıflatır.</p>\n<p>Özetle: filigran korur ama fotoğrafı bozmamalıdır. Adımlar için <a href=\"/tr/blog/gorsele-filigran-nasil-eklenir\">Görsele filigran nasıl eklenir</a> yazısına bakın; en iyi uygulamalar için <a href=\"/tr/blog/filigran-en-iyi-uygulamalar\">filigran en iyi uygulamaları</a> yazısı yardımcı olur. Metin için <a href=\"/tr/gorsele-metin-ekle\">görsele metin ekleme</a> hazırdır; araç ise <a href=\"/tr/gorsel-filigran-ekle\">görsel filigran</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Müşteri önizlemelerinde en iyi filigran opaklığı nedir?","answer":"Yüzde 40-50 opaklık en iyisidir. Filigran okunur ama fotoğraf görülür. Döşemeli desen kullanın; tek filigran kırpmayla gider, desen gitmez. Ödeme sonrası filigransız sürümü teslim edin."},{"question":"Sosyal medyada paylaştığım fotoğraflara filigran koymalı mıyım?","answer":"Evet, hafif bir filigran koyun. Yüzde 20-30 opaklık, markayı duyurur ama görseli bozmaz. Filigranı köşeye koymayın; platform görseli kırpabilir. Marka adını filigrana ekleyin."},{"question":"Bir görselden filigran kaldırılabilir mi?","answer":"Bazen, ama her zaman değil. Tek ve hafif filigran kaldırılabilir; döşemeli desen kaldırılması çok zordur. Yapay zekâ bazen siler ama fotoğrafı da bozar. Filigran, izinsiz kullanımı caydırır ama engelleyemez."},{"question":"Filigran logom hangi dosya türünde olmalı?","answer":"PNG olmalıdır. PNG saydamlığı destekler; logo arka plansız durur. JPG saydamlığı desteklemez; logo beyaz kutuyla gelir. Logoyu yüksek çözünürlükte hazırlayın."},{"question":"Filigranlamak fotoğrafımın kalitesini düşürür mü?","answer":"Hayır, filigran kaliteyi düşürmez; yalnızca görselin üzerine işaret ekler. Ancak çok opak filigran, fotoğrafın görünümünü bozar. Opaklığı düşük tutun; fotoğraf hâlâ görülmelidir."},{"question":"Müşteri fotoğraflarını tarayıcı aracında filigranlamak güvenli mi?","answer":"Evet. Araç tamamen tarayıcıda çalışır; fotoğraflarınız sunucuya yüklenmez. İş bitince tarayıcı verisi silinir. Gizli müşteri işlerini güvenle filigranlayabilirsiniz."}];
